corrected_code:
const twilio = require('twilio');

app.post('/webhooks/twilio/call-recording', async (req, res) => {
  const twilioSignature = req.headers['x-twilio-signature'];
  const fullUrl = `${process.env.APP_BASE_URL}${req.originalUrl}`;
  const isValid = twilio.validateRequest(process.env.TWILIO_AUTH_TOKEN, twilioSignature, fullUrl, req.body);

  if (!isValid) return res.status(403).send('Invalid Twilio signature');

  const { RecordingUrl, CallSid, Duration, From } = req.body;
  const ticketId = req.query.supportTicketId;

  const ticket = await SupportTicket.findOne({ id: ticketId });
  if (!ticket || ticket.customerPhone !== From) {
    return res.status(403).send('Caller phone number does not match registered ticket submitter');
  }

  await SupportTicketAttachment.create({
    ticketId,
    mediaUrl: RecordingUrl,
    callSid: CallSid,
    durationSeconds: Duration,
    attachedAt: new Date()
  });

  res.type('text/xml').send('<Response></Response>');
});
